import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Absolute R — technical reference","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/ABSOLUTE.html"}],["meta",{"property":"og:title","content":"Absolute R — technical reference | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/ABSOLUTE.html"}],["meta",{"name":"twitter:title","content":"Absolute R — technical reference | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"strategies/ABSOLUTE.md","filePath":"strategies/ABSOLUTE.md","lastUpdated":1793949601000}`),a={name:`strategies/ABSOLUTE.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="absolute-r-—-technical-reference" tabindex="-1">Absolute R — technical reference <a class="header-anchor" href="#absolute-r-—-technical-reference" aria-label="Permalink to “Absolute R — technical reference”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Absolute R is the exhaustive branch-and-bound portfolio optimiser for the <strong>scoped date-range objective</strong>. It explores feasible decisions within the requested start and end dates and uses a feasible incumbent plus admissible upper bounds to prune branches that cannot improve the terminal portfolio outcome.</p><p><strong>Implementation:</strong> <code>src/strategies/absolute.js</code> and <code>src/strategies/search-strategy-base.js</code>.</p><h2 id="planning-model" tabindex="-1">Planning model <a class="header-anchor" href="#planning-model" aria-label="Permalink to “Planning model”">​</a></h2><ol><li>Build a simulation context containing accounts, eligible FD products, cash-flow schedules, transfer fees and the scoped investment horizon.</li><li>Run Greedy to obtain a feasible incumbent.</li><li>Expand each search state into feasible local booking, consolidation and carry decisions.</li><li>Advance candidates to the next relevant event date, including FD cash flows/maturities, inflows and outflows.</li><li>Apply scoped dominance, memoisation and admissible terminal-value bounds.</li><li>Continue until the feasible search space is exhausted, then emit the best decision path for authoritative runtime execution.</li></ol><p>Unlike Absolute R+, Absolute R does not retain a fixed-width beam or truncate local booking combinations.</p><h2 id="candidate-generation-and-feasibility" tabindex="-1">Candidate generation and feasibility <a class="header-anchor" href="#candidate-generation-and-feasibility" aria-label="Permalink to “Candidate generation and feasibility”">​</a></h2><p>Absolute R maximises the scoped terminal portfolio outcome under the supplied model. The search respects:</p><ul><li>Account and FD-product compatibility.</li><li>Minimum booking amounts and account eFD eligibility.</li><li>Scheduled and recurring inflows.</li><li>Strict, deferred and best-effort outflow policies.</li><li>Transfer fees and consolidation constraints.</li><li>AIT, interest payout and maturity rules.</li><li>The selected investment start and end dates.</li></ul><p>The simulation runtime remains authoritative for actual event processing, balance mutation, outflow settlement and finalisation.</p><h2 id="optimality-and-limitations" tabindex="-1">Optimality and limitations <a class="header-anchor" href="#optimality-and-limitations" aria-label="Permalink to “Optimality and limitations”">​</a></h2><p>Absolute R can report <code>optimality_proven: true</code> when its scoped branch-and-bound search completes and all applied bounds and dominance rules remain valid. This is a proof relative to the supplied FD catalogue, account capabilities, cash-flow schedules, fees, tax and interest assumptions—not a guarantee about future bank rates or real-world outcomes outside the model.</p><h2 id="search-limits" tabindex="-1">Search limits <a class="header-anchor" href="#search-limits" aria-label="Permalink to “Search limits”">​</a></h2><p>The decision space grows rapidly with the number of accounts, eligible FD products, relevant event dates, split/consolidation combinations and cash-flow schedules. Dominance, memoisation and bound pruning reduce work but do not remove worst-case combinatorial growth. Absolute R is therefore CLI-only.</p><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to “Diagnostics”">​</a></h2><p>Inspect search diagnostics and <code>optimality_proven</code> with every result. Net interest alone does not establish whether the exhaustive search proved an optimum.</p><h2 id="configuration-and-compatibility" tabindex="-1">Configuration and compatibility <a class="header-anchor" href="#configuration-and-compatibility" aria-label="Permalink to “Configuration and compatibility”">​</a></h2><p>The public display name is <strong>Absolute R</strong>, where R denotes the scoped date range. The JSON strategy identifier remains <code>absolute</code>; the CLI accepts both <code>absolute-r</code> and the legacy <code>absolute</code> alias.</p><h2 id="runtime-boundary" tabindex="-1">Runtime boundary <a class="header-anchor" href="#runtime-boundary" aria-label="Permalink to “Runtime boundary”">​</a></h2><p>Absolute R produces a candidate decision path; it does not execute hypothetical bookings or mutate authoritative balances. The selected path is replayed by <code>SimulationRuntime</code>, which validates and executes the decisions against actual events and balances.</p><h2 id="source-map" tabindex="-1">Source map <a class="header-anchor" href="#source-map" aria-label="Permalink to “Source map”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Exhaustive search and branch-and-bound</td><td><code>src/strategies/absolute.js</code>, <code>src/strategies/search-strategy-base.js</code></td></tr><tr><td>Authoritative event processing and decision execution</td><td><code>src/core/simulation-runtime.js</code></td></tr><tr><td>Session driving and finalisation</td><td><code>src/core/simulation.js</code></td></tr></tbody></table>`,23)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};